/* main.c - the guest's process entry (the one definition of `main`).
 * crt0 -> __fnvnx_guest_entry (runtime.c: bss, relocation, TLS, newlib, files, init arrays) -> main -> fnvnx_exe_entry, the lifted entry
 * point of the game's exe (hostabi guest.h: generated by the product ELF root from the PE AddressOfEntryPoint, defined by nothing else).
 * argc/argv/envp are what runtime.c passes (the process environment of the declared machine); the exe's entry takes no arguments. */
#include <stdint.h>

#include "fnvnx/guest.h"

int main(int argc, char **argv, char **envp)
{
    (void)argc;
    (void)argv;
    (void)envp;
    return (int)fnvnx_exe_entry();
}
